#include "gateway_warehouse_page.h"

const char GATEWAY_WAREHOUSE_PAGE[] =
"<!doctype html><html lang='vi'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='color-scheme' content='dark'><title>AUBOT | Kho</title><link rel='stylesheet' href='/ui.css'><style>"
".warehouse-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.warehouse-tile{position:relative;min-height:142px;padding:15px;border:1px solid var(--line);border-radius:15px;background:var(--glass);color:var(--text);text-align:left;cursor:pointer}.warehouse-tile:hover{border-color:#526783}.warehouse-tile .group{color:#a5b4fc;font-size:10px;font-weight:850;letter-spacing:.1em}.warehouse-tile .code{display:block;margin-top:6px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:17px}.warehouse-tile .state{display:block;margin-top:18px;font-size:15px;font-weight:850}.warehouse-tile .meta{display:flex;align-items:center;gap:7px;margin-top:7px;color:var(--muted);font-size:11px}.warehouse-tile.EMPTY{border-color:rgba(52,211,153,.4);background:linear-gradient(145deg,rgba(20,53,48,.85),var(--glass))}.warehouse-tile.EMPTY .state{color:#86efac}.warehouse-tile.OCCUPIED{border-color:rgba(251,191,36,.48);background:linear-gradient(145deg,rgba(64,47,20,.8),var(--glass))}.warehouse-tile.OCCUPIED .state{color:#fde68a}.warehouse-tile.UNKNOWN .state{color:#cbd5e1}.section-block{margin-top:13px;padding-top:13px;border-top:1px solid var(--line2)}.section-title{display:flex;align-items:center;gap:9px;margin:0 0 10px;font-size:14px}.runtime-box{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.runtime-box div{padding:9px;border:1px solid var(--line2);border-radius:8px;background:var(--glass2)}.runtime-box small{display:block;color:var(--muted);font-size:10px}.runtime-box b{display:block;margin-top:3px;font-size:12px}@media(max-width:760px){.warehouse-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:390px){.warehouse-grid{grid-template-columns:1fr}.runtime-box{grid-template-columns:1fr}}"
"</style></head><body data-page='factory'><div class='shell'><header class='hero'><div class='brand'><img class='logo' src='/logo.png' alt='AUBOT'><div><div class='eyebrow'>AUBOT · WAREHOUSE GATEWAY</div><h1>Giám sát trạng thái kho</h1><p>Trạng thái vị trí theo thời gian thực</p></div></div><div class='header-status'><div data-app-user></div><div class='status-chip identity'><i></i><small>Gateway</small><b data-gw>--</b></div><div class='status-chip' data-network-chip><i></i><small>Mạng</small><b data-network>Đang đọc</b></div><div class='status-chip' data-mqtt-chip><i></i><small>MQTT</small><b data-mqtt>Đang đọc</b></div></div></header><nav class='nav' data-app-nav aria-label='Điều hướng chính'><a href='/'>TỔNG QUAN</a></nav>"
"<section class='toolbar'><div class='segmented' aria-label='Chọn profile'><button class='btn' id='p8'>8 GROUP</button><button class='btn' id='p12'>12 GROUP</button></div><div id='summary' class='summary-line'>Đang đọc trạng thái…</div></section><main id='grid' class='warehouse-grid'></main></div>"
"<dialog id='dlg'><header class='dialog-head'><div><div class='eyebrow'>CẤU HÌNH VỊ TRÍ</div><h2 id='dialogTitle'>Group</h2></div><button class='btn ghost' type='button' id='closeDialog'>Đóng</button></header><form id='form' class='dialog-body'>"
"<section><h3 class='section-title'><span class='step'>01</span>Vị trí</h3><div class='fields'><label class='field'><span>Mã kho</span><input id='code' maxlength='15' required></label><label class='field'><span>Tên vị trí</span><input id='name' maxlength='31'></label><label class='switch-line full'><span>Bật quản lý vị trí</span><input id='enabled' type='checkbox'></label></div></section>"
"<section class='section-block'><h3 class='section-title'><span class='step'>02</span>Laser</h3><div class='fields'><label class='field'><span>LaserID</span><select id='laser'></select></label><label class='field'><span>Phạm vi cho phép</span><input id='range' readonly></label></div></section>"
"<section class='section-block'><h3 class='section-title'><span class='step'>03</span>Vùng phát hiện</h3><div class='fields'><label class='field'><span>Khoảng cách (mm)</span><input id='distance' type='number' min='0' max='1200'></label><label class='field'><span>Khẩn cấp (mm)</span><input id='emergency' type='number' min='0' max='1200'></label><label class='switch-line full'><span>Bật phát hiện vật cản</span><input id='proximity' type='checkbox'></label></div><details style='margin-top:11px'><summary>Thiết lập nâng cao</summary><div class='details-body fields'><label class='field'><span>Mặt nạ hàng</span><input id='row' type='number' min='0' max='255'></label><label class='field'><span>Mặt nạ cột</span><input id='col' type='number' min='0' max='255'></label></div></details></section>"
"<section class='section-block'><h3 class='section-title'><span class='step'>04</span>Trạng thái realtime</h3><div id='runtime' class='runtime-box'></div></section><div id='err' class='message' role='status' aria-live='polite'></div><div id='applyHint' class='hint'>Bạn cần lưu mapping hợp lệ trước khi áp dụng xuống Laser.</div><div class='dialog-actions'><button class='btn ghost' type='button' id='cancel'>Hủy</button><button class='btn secondary' type='button' id='applyLaser' disabled>Áp dụng xuống Laser</button><button class='btn primary' id='saveMapping' type='submit'>Lưu mapping</button></div></form></dialog>"
"<script src='/ui.js'></script><script>const $=x=>document.getElementById(x);let snap,nodes=[],editing=0,savedSignature='';const esc=x=>String(x===undefined||x===null?'':x).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));function uiStatus(){fetch('/api/ui/status',{cache:'no-store'}).then(r=>r.json()).then(x=>{document.querySelector('[data-gw]').textContent=x.gateway_id;document.querySelector('[data-network]').textContent=x.network?x.network_name:'Chưa kết nối';document.querySelector('[data-mqtt]').textContent=x.mqtt?'Đã kết nối':'Chưa kết nối';document.querySelector('[data-network-chip]').classList.toggle('ok',x.network);document.querySelector('[data-mqtt-chip]').classList.toggle('ok',x.mqtt)}).catch(()=>{})}"
"async function load(){try{snap=await(await fetch('/api/factory/status',{cache:'no-store'})).json();try{nodes=(await(await fetch('/api/factory/lasers',{cache:'no-store'})).json()).nodes||[]}catch(e){}render()}finally{setTimeout(load,1000)}}function label(s){return s==='EMPTY'?'KHÔNG CÓ HÀNG':s==='OCCUPIED'?'CÓ HÀNG':'CHƯA XÁC ĐỊNH'}function warnLabel(s){return s==='CLEAR'?'KHÔNG CÓ VẬT':s==='NORMAL'||s==='EMERGENCY'?'CÓ VẬT':'CHƯA XÁC ĐỊNH'}function runtime(p){$('runtime').innerHTML=`<div><small>Trạng thái</small><b>${label(p.state)}</b></div><div><small>Cảm biến</small><b>${p.sensor_online?'ONLINE':'OFFLINE'}</b></div><div><small>Vật cản</small><b>${warnLabel(p.warn)}</b></div>`}function render(){$('p8').classList.toggle('active',snap.profile==='GROUP_8');$('p12').classList.toggle('active',snap.profile==='GROUP_12');$('summary').innerHTML=`<b>${snap.group_count} vị trí</b> · ${snap.online} online · ${snap.occupied} có hàng`;$('grid').innerHTML=snap.positions.map(p=>`<button class='warehouse-tile ${p.state}' data-group='${p.group_id}'><span class='group'>GROUP ${p.group_id}</span><strong class='code'>${esc(p.warehouse_code||'Chưa cấu hình')}</strong><span class='state'>${label(p.state)}</span><span class='meta'><i class='dot ${p.sensor_online?'ok':'bad'}'></i>Laser ${String(p.laser_id||'--').padStart(2,'0')} · ${p.sensor_online?'ONLINE':'OFFLINE'}</span></button>`).join('');document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>openGroup(Number(b.dataset.group)));if($('dlg').open&&editing&&snap.positions[editing-1]){const p=snap.positions[editing-1];savedSignature=signature(p);runtime(p);syncApply()}}"
"function formData(){return {group_id:editing,laser_id:$('laser').value,warehouse_code:$('code').value.trim(),warehouse_name:$('name').value.trim(),distance_mm:$('distance').value,emergency_mm:$('emergency').value,low_col:$('col').value,high_row:$('row').value,enabled:$('enabled').checked?1:0,proximity:$('proximity').checked?1:0}}function signature(x){return [Number(x.group_id),Number(x.laser_id),String(x.warehouse_code||''),String(x.warehouse_name||''),Number(x.distance_mm??x.config_distance_mm),Number(x.emergency_mm??x.config_emergency_mm),Number(x.low_col),Number(x.high_row),Number(x.enabled),Number(x.proximity??x.proximity_enabled)].join('|')}function message(text,type=''){$('err').textContent=text;$('err').className='message'+(type?' '+type:'')}function syncApply(){const p=snap&&snap.positions[editing-1],same=signature(formData())===savedSignature,ready=!!(p&&p.enabled&&p.laser_id&&same);$('applyLaser').disabled=!ready;$('applyHint').textContent=ready?'Mapping đã lưu. Bạn có thể áp dụng cấu hình xuống Laser.':same?'Vị trí phải được bật và gán LaserID trước khi áp dụng.':'Dữ liệu đang thay đổi. Hãy lưu mapping hợp lệ trước khi áp dụng xuống Laser.'}function apiError(code){code=String(code||'').trim();const map={DUPLICATE_WAREHOUSE_CODE:`Mã kho ${$('code').value.trim()||'này'} đã được sử dụng ở vị trí khác. Hãy nhập mã kho khác.`,DUPLICATE_LASER_ID:'LaserID này đã được gán cho vị trí khác. Hãy chọn LaserID khác.',LASER_OUT_OF_GROUP:'LaserID nằm ngoài phạm vi cho phép của Group này.',INVALID_GROUP:'Group không hợp lệ.',INVALID_DISTANCE:'Khoảng cách phải nằm trong phạm vi 0–1200 mm.',INVALID_TEXT:'Mã kho hoặc tên vị trí chứa dữ liệu không hợp lệ.',PROFILE_CONFLICT:'Mapping hiện tại xung đột với profile đang chọn.'};return map[code]||code||'Không thể lưu mapping. Vui lòng thử lại.'}"
"function openGroup(g){editing=g;const p=snap.positions[g-1],a=p.allowed_first,b=p.allowed_last;$('dialogTitle').textContent='Group '+g;$('range').value=`ID ${a}–${b}`;$('laser').innerHTML='<option value=0>Chưa gán</option>'+Array.from({length:b-a+1},(_,i)=>a+i).map(id=>{const n=nodes.find(x=>x.id===id),used=snap.positions.some(x=>x.group_id!==g&&x.laser_id===id);return `<option value=${id} ${used?'disabled':''}>ID ${id} · ${n&&n.alive?'ONLINE':'CHƯA PHÁT HIỆN'}${used?' · ĐÃ DÙNG':''}</option>`}).join('');$('laser').value=p.laser_id||0;$('code').value=p.warehouse_code||'';$('name').value=p.warehouse_name||'';$('distance').value=p.config_distance_mm??600;$('emergency').value=p.config_emergency_mm??300;$('row').value=p.high_row??0;$('col').value=p.low_col??0;$('enabled').checked=p.enabled;$('proximity').checked=p.proximity_enabled;runtime(p);savedSignature=signature(p);message('');syncApply();$('dlg').showModal()}"
"async function profile(p){if(snap.profile===p)return;if(!confirm('Đổi profile kho? Mapping xung đột sẽ bị từ chối.'))return;const r=await fetch('/api/factory/profile',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({profile:p,clear_conflicts:0})});if(!r.ok)alert('Mapping hiện tại xung đột với profile mới.');else load()}async function applyLaser(){const p=snap.positions[editing-1];if($('applyLaser').disabled||!p)return;const laserId=p.laser_id;if(!confirm(`Áp dụng vùng phát hiện đã lưu xuống Laser ${laserId}? Cảm biến trong nhóm có thể khởi động lại.`))return;$('applyLaser').disabled=true;message('Đang gửi yêu cầu cấu hình…');try{const r=await fetch('/api/factory/laser/apply',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({group_id:editing})});if(!r.ok)throw Error(await r.text());message('Đã gửi cấu hình xuống Laser. Đang chờ cảm biến xác nhận.','ok')}catch(e){message('Không thể áp dụng: '+apiError(e.message),'bad')}finally{syncApply()}}$('p8').onclick=()=>profile('GROUP_8');$('p12').onclick=()=>profile('GROUP_12');$('applyLaser').onclick=applyLaser;$('closeDialog').onclick=$('cancel').onclick=()=>$('dlg').close();$('form').addEventListener('input',()=>{message('');syncApply()});$('form').addEventListener('change',()=>{message('');syncApply()});$('form').onsubmit=async e=>{e.preventDefault();const p=formData(),save=$('saveMapping');save.disabled=true;message('Đang lưu mapping…');try{const r=await fetch('/api/factory/warehouse',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(p)});if(!r.ok)throw Error(await r.text());const sr=await fetch('/api/factory/status',{cache:'no-store'});if(!sr.ok)throw Error(await sr.text());snap=await sr.json();render();savedSignature=signature(snap.positions[editing-1]);message('Đã lưu mapping. Bạn có thể áp dụng cấu hình xuống Laser.','ok');syncApply()}catch(x){message(apiError(x.message),'bad');syncApply()}finally{save.disabled=false}};uiStatus();setInterval(uiStatus,2500);load()</script></body></html>";
